using sv_42d057acccc14e5492e2119031814db7.Models;

namespace sv_42d057acccc14e5492e2119031814db7.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with tomato sauce, mozzarella, and fresh basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with pancetta, egg yolk, and pecorino romano.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 45),
            new(4, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked in broth with parmesan.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, chili peppers, and vegetables.", 35),
            new(6, "Mapo Tofu", "Silken tofu in a fiery Sichuan peppercorn and chili bean sauce.", 20),
            new(7, "Xiaolongbao", "Steamed soup dumplings filled with pork and rich broth.", 90),
            new(8, "Char Siu", "Cantonese-style barbecued pork glazed with honey and five-spice.", 60),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Spit-roasted pork tacos with pineapple, onion, and cilantro.", 50),
            new(10, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(11, "Chiles en Nogada", "Stuffed poblano peppers with walnut cream sauce and pomegranate.", 75),
            new(12, "Elote", "Grilled Mexican street corn with mayo, cotija cheese, and chili powder.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject NavigationManager Navigation
@inject ILogger<Recipes> Logger

@using sv_42d057acccc14e5492e2119031814db7.Models
@using sv_42d057acccc14e5492e2119031814db7.Services

<PageTitle>Recipes</PageTitle>

<h1>Recipes — @GetCuisineName(CuisineId)</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn btn-outline-primary me-1">Italian</a>
    <a href="/recipes/2" class="btn btn-outline-primary me-1">Chinese</a>
    <a href="/recipes/3" class="btn btn-outline-primary me-1">Mexican</a>
</nav>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <div class="d-flex align-items-center my-4">
        <div class="spinner-border text-primary me-2" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block mb-3" role="status">
            <small>Refreshing…</small>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-2 g-3">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private bool _isRefreshing;
    private string? _errorMessage;

    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine actually changes.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync(CuisineId);
    }

    private async Task LoadRecipesAsync(int cuisineId)
    {
        // Cancel any in-flight request for a previous cuisine.
        await CancelPendingLoadAsync();

        _errorMessage = null;

        if (_recipes is null)
        {
            _isLoading = true;
        }
        else
        {
            _isRefreshing = true;
        }

        var cts = new CancellationTokenSource();
        _loadCts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, cts.Token);

            // Guard: if this request was cancelled while awaiting, discard the result.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = result;
            _loadedCuisineId = cuisineId;
            _errorMessage = null;
        }
        catch (OperationCanceledException)
        {
            // Expected when the user switches cuisine or navigates away — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isLoading = false;
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync(CuisineId);
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return Enumerable.Empty<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
            "newest" => _recipes.OrderByDescending(r => r.Id),
            _ => _recipes,
        };
    }

    private static string GetCuisineName(int id) => id switch
    {
        1 => "Italian",
        2 => "Chinese",
        3 => "Mexican",
        _ => "Unknown",
    };

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

